1	// marktdaten/page.js – Marktdaten-Hub Freiflächen-PV (EEG-Ausschreibungen, Marktwert Solar, Capture Rate, Zubau, Pacht)
2	//
3	// Sprachmodell: deutsche Texte direkt, englische Texte in EN (unten); Zahlen im Format der Sprache.
4	
5	import Link from "@/components/Land/Link";
6	import { ArrowRight, BarChart3, Database, ExternalLink, Gavel, Sun, TrendingDown, Zap } from "lucide-react";
7	import Section from "@/components/ui/Section";
8	import SectionHeading from "@/components/ui/SectionHeading";
9	import Faq from "@/components/ui/Faq";
10	import CtaBand from "@/components/ui/CtaBand";
11	import Reveal from "@/components/ui/Reveal";
12	import Querverweise from "@/components/Reusable/Querverweise";
13	import { rechnerMetadata, rechnerMetadataEn } from "@/components/Rechner/RechnerSeite";
14	import AusschreibungsChart from "@/components/Marktdaten/AusschreibungsChart";
15	import MarktwertChart from "@/components/Marktdaten/MarktwertChart";
16	import LiveEinordnung from "@/components/Marktdaten/LiveEinordnung";
17	import Hero from "@/components/Marktdaten/Seite/Hero";
18	import Kennzahlen from "@/components/Marktdaten/Seite/Kennzahlen";
19	import { abs } from "@/data/site";
20	import {
21	  AUSSCHREIBUNGEN,
22	  AUSSCHREIBUNGEN_JAHR,
23	  MARKTWERTE,
24	  MARKTWERT_SOLAR_FRUEHER,
25	  NEGATIVE_STUNDEN,
26	  ZUBAU,
27	  MARKTDATEN_QUELLEN,
28	  MARKTDATEN_STAND,
29	  MARKTDATEN_STAND_TEXT,
30	  NAECHSTER_GEBOTSTERMIN,
31	  LETZTE_AUSSCHREIBUNG,
32	  LETZTER_MARKTWERT,
33	  MIN_ZUSCHLAG,
34	  MAX_ZUSCHLAG,
35	  SUMME_ZUSCHLAG_MW,
36	  LANDPACHT_DESTATIS,
37	} from "@/data/marktdaten";
38	import { PACHT, ERLOESE, FREIFLAECHE } from "@/lib/invest/markt";
39	import { fmt } from "@/lib/rechner/annahmen";
40	import { getEnergySnapshot } from "@/lib/energy";
41	import JsonLd from "@/components/JsonLd";
42	import { pfad as seitenPfad } from "@/lib/land";
43	import { seitenLand, seitenMetadata, spracheDerAnfrage } from "@/lib/land/seite";
44	import { uebersetze } from "@/lib/sprache/woerterbuch";
45	import { formate } from "@/lib/sprache/zahlformat";
46	import { datumText } from "@/lib/sprache/format";
47	import { GiltFuer, LandHinweis } from "@/components/Land/LandHinweis";
48	import { faqFuerLand } from "@/components/Land/Laenderteile";
49	
50	export const revalidate = 900;
51	
52	const PFAD = seitenPfad("/marktdaten");
53	const PAGE_URL = abs(PFAD);
54	
55	const metadata = rechnerMetadata({
56	  pfad: PFAD,
57	  title: "Marktdaten Solar: EEG-Zuschläge & Marktwert | ÖkoInvest",
58	  description:
59	    "Marktdaten Freiflächen-PV: EEG-Zuschlagswerte seit 2017, Höchstwerte, Gebotsmengen, Marktwert Solar, Capture Rate, Zubau DACH und Pacht – mit Quellen.",
60	  keywords: [
61	    "EEG Ausschreibung Solar Ergebnisse",
62	    "Zuschlagswert Solar Freifläche",
63	    "Marktwert Solar Jahresmarktwert",
64	    "Capture Rate Solar Deutschland",
65	    "Solarpark Marktdaten",
66	    "negative Strompreise Stunden",
67	    "PV Zubau Freifläche",
68	  ],
69	});
70	
71	const metadataEn = rechnerMetadataEn({
72	  title: "Solar market data: EEG awards & market value | ÖkoInvest",
73	  description:
74	    "Market data for ground-mounted PV: EEG award values since 2017, maximum values, bid volumes, solar market value, capture rate, additions in DACH and lease – with sources.",
75	  keywords: [
76	    "EEG solar tender results",
77	    "award value ground-mounted solar",
78	    "solar market value annual",
79	    "solar capture rate Germany",
80	    "solar park market data",
81	    "negative electricity prices hours",
82	    "ground-mounted PV additions",
83	  ],
84	});
85	
86	/* ------------------------------------------------------------------ */
87	/* Abgeleitete Aussagen                                                */
88	/* ------------------------------------------------------------------ */
89	
90	const MONATE = ["Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August", "September", "Oktober", "November", "Dezember"];
91	const termin = (iso) => `${Number(iso.slice(8, 10))}. ${MONATE[Number(iso.slice(5, 7)) - 1]} ${iso.slice(0, 4)}`;
92	const ct = (v, s = 2) => `${fmt(v, s)} ct/kWh`;
93	const L = LETZTE_AUSSCHREIBUNG;
94	const VORLETZTE = AUSSCHREIBUNGEN[AUSSCHREIBUNGEN.length - 2];
95	const JAHR_2025 = AUSSCHREIBUNGEN_JAHR.find((j) => j.jahr === 2025);
96	const MW_2020 = MARKTWERTE.find((m) => m.jahr === 2020);
97	const NEG_2025 = NEGATIVE_STUNDEN.find((n) => n.jahr === 2025);
98	const NEG_2022 = NEGATIVE_STUNDEN.find((n) => n.jahr === 2022);
99	const ERSTER = AUSSCHREIBUNGEN[0];
100	const SEIT_2024 = AUSSCHREIBUNGEN.filter((a) => a.datum >= "2024").reduce((r, a) => ({ min: Math.min(r.min, a.mittel), max: Math.max(r.max, a.mittel) }), { min: Infinity, max: -Infinity });
101	const faktorAcker = PACHT.freiflaecheProHa.mittel / LANDPACHT_DESTATIS.schnitt;
102	
103	const ANTWORT = `Beim letzten Gebotstermin am ${termin(L.datum)} lag der mengengewichtete Zuschlagswert für Freiflächen-Solaranlagen bei ${ct(L.mittel)} (Vorrunde: ${ct(VORLETZTE.mittel)}). Seit ${ERSTER.datum.slice(0, 4)} schwankten die Ergebnisse zwischen ${ct(MIN_ZUSCHLAG.mittel)} (${termin(MIN_ZUSCHLAG.datum)}) und ${ct(MAX_ZUSCHLAG.mittel)} (${termin(MAX_ZUSCHLAG.datum)}).`;
104	
105	const KENNZAHLEN = [
106	  // zahl/stellen: dieselben Werte wie `wert`, als Zahl für den Count-up (nur Werte, die auf der Seite stehen)
107	  { icon: Gavel, wert: fmt(L.mittel, 2), zahl: Number(L.mittel.toFixed(2)), stellen: 2, einheit: "ct/kWh", text: `Ø Zuschlag Solar, ${termin(L.datum)}` },
108	  { icon: BarChart3, wert: fmt(L.gebote / L.volumen, 1), zahl: Number((L.gebote / L.volumen).toFixed(1)), stellen: 1, einheit: "fach", text: `überzeichnet im ${MONATE[Number(L.datum.slice(5, 7)) - 1]} ${L.datum.slice(0, 4)}` },
109	  { icon: Sun, wert: fmt(LETZTER_MARKTWERT.capture * 100), zahl: Math.round(LETZTER_MARKTWERT.capture * 100), stellen: 0, einheit: "%", text: `Capture Rate Solar ${LETZTER_MARKTWERT.jahr}` },
110	  { icon: TrendingDown, wert: fmt(NEG_2025.stunden), zahl: Math.round(NEG_2025.stunden), stellen: 0, einheit: "h", text: `Stunden mit negativem Preis ${NEG_2025.jahr}` },
111	];
112	
113	const PHASEN_TEXT = [
114	  {
115	    titel: "2017–2021: Kostenverfall und stabiler Wettbewerb",
116	    text: `Von ${ct(ERSTER.mittel)} im Februar 2017 fielen die Zuschläge binnen eines Jahres auf ${ct(4.33)}. Danach pendelten sie sich – mit Ausreißern bei den Sonderausschreibungen 2019 – um 5 ct ein – bei zunächst kleinen Ausschreibungsmengen von 100 bis 600 MW je Termin.`,
117	  },
118	  {
119	    titel: "2022–2023: Zinswende, Lieferketten, höherer Höchstwert",
120	    text: "2022 blieben einzelne Runden unterzeichnet, die Zuschläge stiegen bis an den Höchstwert. Die Bundesnetzagentur hob den Höchstwert für 2023 auf 7,37 ct an – im März 2023 lag der Durchschnitt mit 7,03 ct auf dem höchsten Stand seit 2017.",
121	  },
122	  {
123	    titel: "Seit 2024: große Volumen, starker Wettbewerb",
124	    text: `Mit Ausschreibungsmengen von über 2 GW je Termin und deutlicher Überzeichnung liegen die Ergebnisse wieder zwischen ${fmt(SEIT_2024.min, 2)} und ${fmt(SEIT_2024.max, 2)} ct. 2025 wurden in drei Runden zusammen rund ${fmt(JAHR_2025.zuschlag / 1000, 1)} GW bezuschlagt, im Mittel ${ct(JAHR_2025.mittel)}.`,
125	  },
126	];
127	
128	const FAQ = [
129	  {
130	    q: "Wie hoch ist der aktuelle Zuschlagswert für Freiflächen-Solaranlagen?",
131	    a: `Beim Gebotstermin am ${termin(L.datum)} lag der mengengewichtete durchschnittliche Zuschlagswert bei ${ct(L.mittel)}; bezuschlagt wurden Gebote zwischen ${ct(L.min)} und ${ct(L.max)}. Der Höchstwert betrug ${ct(L.hoechst)}. Der nächste reguläre Gebotstermin ist der ${NAECHSTER_GEBOTSTERMIN}.`,
132	    nurDE: true,
133	  },
134	  {
135	    q: "Was bedeutet „mengengewichteter Zuschlagswert“?",
136	    a: "Jeder bezuschlagte Bieter erhält seinen eigenen Gebotswert (Pay-as-bid). Der mengengewichtete Durchschnitt gewichtet diese Werte mit der jeweiligen Leistung – große Parks zählen also stärker als kleine. Er ist die übliche Kennzahl, um Gebotstermine zu vergleichen.",
137	  },
138	  {
139	    q: "Was ist der Unterschied zwischen Zuschlagswert und Marktwert Solar?",
140	    a: "Der Zuschlagswert ist der anzulegende Wert, den ein Park über 20 Jahre als Untergrenze seiner Erlöse erhält – die Differenz zum Marktwert zahlt das EEG-Konto als Marktprämie. Der Marktwert Solar ist das, was Solarstrom an der Börse tatsächlich im Schnitt erlöst. Liegt der Marktwert über dem Zuschlagswert, entfällt die Prämie.",
141	  },
142	  {
143	    q: "Was ist die Capture Rate und warum sinkt sie?",
144	    a: `Die Capture Rate setzt den Jahresmarktwert Solar ins Verhältnis zum durchschnittlichen Börsenpreis. ${LETZTER_MARKTWERT.jahr} lag sie bei rund ${fmt(LETZTER_MARKTWERT.capture * 100)} %, ${MW_2020.jahr} noch bei ${fmt(MW_2020.capture * 100)} %. Weil immer mehr Solaranlagen gleichzeitig mittags einspeisen, sinkt der Preis genau dann, wenn Solarparks produzieren (Kannibalisierung).`,
145	    nurDE: true,
146	  },
147	  {
148	    q: "Wie oft gab es negative Strompreise?",
149	    a: `Nach Auswertung von Energy-Charts-Daten gab es ${NEG_2025.jahr} rund ${fmt(NEG_2025.stunden)} Stunden mit negativem Day-Ahead-Preis, ${NEG_2022.jahr} waren es nur ${fmt(NEG_2022.stunden)}. Für neue Anlagen entfällt in diesen Zeiten die Marktprämie; Speicher und flexible Abnehmer gewinnen deshalb an Wert.`,
150	    nurDE: true,
151	  },
152	  {
153	    q: "Wie aktuell sind die Marktdaten und woher stammen sie?",
154	    a: `Stand der Seite: ${MARKTDATEN_STAND_TEXT}. Ausschreibungsergebnisse stammen von der Bundesnetzagentur, Marktwerte von den Übertragungsnetzbetreibern (netztransparenz.de), negative Stunden aus Energy-Charts (Fraunhofer ISE), Zubauzahlen von Bundesnetzagentur, PV Austria und Swissolar. Den Börsenpreis zeigen wir live. Alle Angaben ohne Gewähr.`,
155	  },
156	];
157	
158	const QUERVERWEISE = [
159	  { href: "/ratgeber/eeg-ausschreibung-freiflaeche", titel: "EEG-Ausschreibung Freifläche", text: "Termine, Voraussetzungen, Sicherheiten und Gebotsstrategie." },
160	  { href: seitenPfad("/rechner/solarpark"), titel: "Solarpark-Renditerechner", text: "IRR und Cashflow mit Zuschlagswert, PPA oder Marktwert rechnen." },
161	  { href: seitenPfad("/energie-live"), titel: "Strommarkt live", text: "Day-Ahead-Preis, Strommix und Capture Rate von heute." },
162	  { href: "/projektboerse", titel: "Projektbörse", text: "Solarprojekte in allen Phasen finden oder anbieten." },
163	];
164	
165	/* ------------------------------------------------------------------ */
166	/* Englisch (Sprachmodell): gleiche Aussagen, englische Texte und Zahlenformate */
167	/* ------------------------------------------------------------------ */
168	
169	const e = formate("en");
170	const MONATE_EN = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
171	const terminEn = (iso) => `${Number(iso.slice(8, 10))} ${MONATE_EN[Number(iso.slice(5, 7)) - 1]} ${iso.slice(0, 4)}`;
172	const ctEn = (v, s = 2) => `${e.fmt(v, s)} ct/kWh`;
173	const STAND_EN = datumText(MARKTDATEN_STAND_TEXT, "en");
174	const NAECHSTER_EN = datumText(NAECHSTER_GEBOTSTERMIN, "en");
175	
176	const ANTWORT_EN = `At the last bidding date on ${terminEn(L.datum)}, the volume-weighted award value for ground-mounted solar installations was ${ctEn(L.mittel)} (previous round: ${ctEn(VORLETZTE.mittel)}). Since ${ERSTER.datum.slice(0, 4)}, results have ranged between ${ctEn(MIN_ZUSCHLAG.mittel)} (${terminEn(MIN_ZUSCHLAG.datum)}) and ${ctEn(MAX_ZUSCHLAG.mittel)} (${terminEn(MAX_ZUSCHLAG.datum)}).`;
177	
178	const EN = {
179	  kennzahlen: [
180	    { wert: e.fmt(L.mittel, 2), text: `Ø solar award, ${terminEn(L.datum)}` },
181	    { wert: e.fmt(L.gebote / L.volumen, 1), einheit: "×", text: `oversubscribed in ${MONATE_EN[Number(L.datum.slice(5, 7)) - 1]} ${L.datum.slice(0, 4)}` },
182	    { wert: e.fmt(LETZTER_MARKTWERT.capture * 100), text: `Solar capture rate ${LETZTER_MARKTWERT.jahr}` },
183	    { wert: e.fmt(NEG_2025.stunden), text: `Hours with negative prices ${NEG_2025.jahr}` },
184	  ],
185	  deutschland: "Germany",
186	  phasen: [
187	    {
188	      titel: "2017–2021: Falling costs and stable competition",
189	      text: `From ${ctEn(ERSTER.mittel)} in February 2017, awards fell to ${ctEn(4.33)} within a year. After that they settled at around 5 ct – with outliers in the special tenders of 2019 – at initially small tender volumes of 100 to 600 MW per bidding date.`,
190	    },
191	    {
192	      titel: "2022–2023: Interest rate turnaround, supply chains, higher maximum value",
193	      text: "In 2022, some rounds were undersubscribed and awards rose up to the maximum value. The Bundesnetzagentur raised the maximum value for 2023 to 7.37 ct – in March 2023 the average reached 7.03 ct, the highest level since 2017.",
194	    },
195	    {
196	      titel: "Since 2024: Large volumes, strong competition",
197	      text: `With tender volumes of over 2 GW per bidding date and clear oversubscription, results are again between ${e.fmt(SEIT_2024.min, 2)} and ${e.fmt(SEIT_2024.max, 2)} ct. In 2025, around ${e.fmt(JAHR_2025.zuschlag / 1000, 1)} GW were awarded in three rounds, at an average of ${ctEn(JAHR_2025.mittel)}.`,
198	    },
199	  ],
200	  faq: [
201	    {
202	      q: "What is the current award value for ground-mounted solar installations?",
203	      a: `At the bidding date on ${terminEn(L.datum)}, the volume-weighted average award value was ${ctEn(L.mittel)}; bids between ${ctEn(L.min)} and ${ctEn(L.max)} were awarded. The maximum value was ${ctEn(L.hoechst)}. The next regular bidding date is ${NAECHSTER_EN}.`,
204	    },
205	    {
206	      q: "What does “volume-weighted award value” mean?",
207	      a: "Each successful bidder receives its own bid value (pay-as-bid). The volume-weighted average weights these values by the respective capacity – so large parks count more than small ones. It is the usual metric for comparing bidding dates.",
208	    },
209	    {
210	      q: "What is the difference between the award value and the solar market value?",
211	      a: "The award value is the anzulegender Wert (reference value) that a park receives as the floor of its revenue for 20 years – the difference to the market value is paid from the EEG account as a market premium. The solar market value is what solar power actually earns on average on the exchange. If the market value is above the award value, the premium does not apply.",
212	    },
213	    {
214	      q: "What is the capture rate and why is it falling?",
215	      a: `The capture rate expresses the annual solar market value as a ratio of the average exchange price. In ${LETZTER_MARKTWERT.jahr} it was around ${e.pct(LETZTER_MARKTWERT.capture * 100)}, in ${MW_2020.jahr} still ${e.pct(MW_2020.capture * 100)}. Because more and more solar plants feed in simultaneously at midday, the price falls exactly when solar parks are producing (cannibalisation).`,
216	    },
217	    {
218	      q: "How often were there negative electricity prices?",
219	      a: `According to an analysis of Energy-Charts data, there were around ${e.fmt(NEG_2025.stunden)} hours with a negative day-ahead price in ${NEG_2025.jahr}, compared with only ${e.fmt(NEG_2022.stunden)} in ${NEG_2022.jahr}. For new plants, the market premium does not apply during these periods; storage and flexible offtakers are therefore gaining in value.`,
220	    },
221	    {
222	      q: "How up to date are the market data and where do they come from?",
223	      a: `Page last updated: ${STAND_EN}. Tender results come from the Bundesnetzagentur (Federal Network Agency), market values from the transmission system operators (netztransparenz.de), negative hours from Energy-Charts (Fraunhofer ISE), addition figures from the Bundesnetzagentur, PV Austria and Swissolar. We show the exchange price live. All information without guarantee.`,
224	    },
225	  ],
226	  querverweise: [
227	    { titel: "EEG tender for ground-mounted PV", text: "Dates, requirements, securities and bidding strategy." },
228	    { titel: "Solar park return calculator", text: "Calculate IRR and cash flow with award value, PPA or market value." },
229	    { titel: "Power market live", text: "Today’s day-ahead price, power mix and capture rate." },
230	    { titel: "Project exchange", text: "Find or offer solar projects in all phases." },
231	  ],
232	  quellen: {
233	    bnetza: "Bundesnetzagentur (Federal Network Agency) – completed tenders for solar installations, first segment (statistics)",
234	    "bnetza-pm": "Bundesnetzagentur – press release of 18 August 2026: results of the bidding date of 1 July 2026",
235	    netztransparenz: "Netztransparenz.de (transmission system operators) – market value overview, annual market values",
236	    dgs: "DGS (German Solar Energy Society) – annual and monthly solar market values 2025 (compiled by Dr Andreas Horn, data from netztransparenz.de and Energy-Charts)",
237	    "zubau-de": "Solarserver – Bundesnetzagentur presents figures on renewable energy expansion in 2025",
238	    "zubau-at": "pv magazine – Austria’s photovoltaic additions fell to 1,634 megawatts in 2025 (PV Austria figures)",
239	    "zubau-ch": "pv magazine – Swissolar expects constant photovoltaic additions of around 1.5 gigawatts",
240	    destatis: "Federal Statistical Office (Destatis) – lease prices for agricultural land (press release 153/2024)",
241	  },
242	  zubau: {
243	    Deutschland: {
244	      land: "Germany",
245	      freiflaeche: "2025 around 8.2 GW – about half of all additions (2024: around a third)",
246	      kumuliert: "just over 117 GW (end of 2025)",
247	      einordnung: "By far the largest ground-mounted market in the DACH region; driven by EEG tenders and unsubsidised PPA parks.",
248	    },
249	    Österreich: {
250	      land: "Austria",
251	      freiflaeche: "no official share published; ground-mounted plants are growing but remain behind rooftop systems",
252	      kumuliert: "just under 9.8 GW (end of 2025)",
253	      einordnung: "The bottleneck is the “Grünland-Photovoltaik” zoning designation (green-land zoning for PV) in each federal state, and grid access.",
254	    },
255	    Schweiz: {
256	      land: "Switzerland",
257	      freiflaeche: "practically no ground-mounted plants on the Swiss Plateau; alpine plants via the “Solarexpress”",
258	      kumuliert: "2025 additions as estimated by Swissolar",
259	      einordnung: "Focus on roofs, façades and large alpine plants; ground-mounted plants outside the building zone only as an exception.",
260	    },
261	  },
262	};
263	
264	
265	/* ------------------------------------------------------------------ */
266	/* JSON-LD                                                             */
267	/* ------------------------------------------------------------------ */
268	
269	const datasetSchema = {
270	  "@context": "https://schema.org",
271	  "@type": "Dataset",
272	  "@id": `${PAGE_URL}/#dataset`,
273	  name: "Marktdaten Freiflächen-Photovoltaik: EEG-Ausschreibungen Solar erstes Segment, Marktwert Solar und Capture Rate",
274	  description:
275	    "Ergebnisse aller Gebotstermine der EEG-Ausschreibungen für Solaranlagen des ersten Segments seit 2017 (Volumen, Gebotsmenge, Zuschlagsmenge, mengengewichteter Zuschlagswert, Spanne, Höchstwert), Jahresmarktwerte Spot und Solar mit Capture Rate seit 2020, Stunden mit negativen Strompreisen sowie Photovoltaik-Zubau in Deutschland, Österreich und der Schweiz.",
276	  url: PAGE_URL,
277	  keywords: ["EEG-Ausschreibung", "Photovoltaik", "Freiflächenanlagen", "Zuschlagswert", "Marktwert Solar", "Capture Rate", "negative Strompreise", "DACH"],
278	  isAccessibleForFree: true,
279	  inLanguage: "de",
280	  creator: { "@type": "Organization", name: "ÖkoInvest GmbH", url: abs("/") },
281	  publisher: { "@id": `${abs("/")}/#organization` },
282	  isBasedOn: MARKTDATEN_QUELLEN.map((q) => q.url),
283	  spatialCoverage: [
284	    { "@type": "Place", name: "Deutschland" },
285	    { "@type": "Place", name: "Österreich" },
286	    { "@type": "Place", name: "Schweiz" },
287	  ],
288	  temporalCoverage: `${ERSTER.datum}/${L.datum}`,
289	  dateModified: MARKTDATEN_STAND,
290	  variableMeasured: [
291	    { "@type": "PropertyValue", name: "Mengengewichteter durchschnittlicher Zuschlagswert", unitText: "ct/kWh" },
292	    { "@type": "PropertyValue", name: "Höchstwert je Gebotstermin", unitText: "ct/kWh" },
293	    { "@type": "PropertyValue", name: "Ausgeschriebene Menge, Gebotsmenge, Zuschlagsmenge", unitText: "MW" },
294	    { "@type": "PropertyValue", name: "Jahresmarktwert Spot und Solar", unitText: "ct/kWh" },
295	    { "@type": "PropertyValue", name: "Capture Rate Solar", unitText: "Prozent" },
296	    { "@type": "PropertyValue", name: "Stunden mit negativem Day-Ahead-Preis", unitText: "h" },
297	  ],
298	};
299	
300	const webPageSchema = {
301	  "@context": "https://schema.org",
302	  "@type": "WebPage",
303	  "@id": `${PAGE_URL}/#webpage`,
304	  url: PAGE_URL,
305	  name: "Marktdaten Freiflächen-PV: EEG-Zuschläge, Marktwert Solar und Capture Rate",
306	  description: ANTWORT,
307	  isPartOf: { "@id": `${abs("/")}/#website` },
308	  about: { "@id": `${PAGE_URL}/#dataset` },
309	  dateModified: MARKTDATEN_STAND,
310	  breadcrumb: {
311	    "@type": "BreadcrumbList",
312	    itemListElement: [
313	      { "@type": "ListItem", position: 1, name: "Startseite", item: abs("/") },
314	      { "@type": "ListItem", position: 2, name: "Ratgeber", item: abs("/ratgeber") },
315	      { "@type": "ListItem", position: 3, name: "Marktdaten", item: PAGE_URL },
316	    ],
317	  },
318	};
319	
320	/* ------------------------------------------------------------------ */
321	
322	function Tabelle({ caption, kopf, zeilen, rechtsAb = 1, minBreite = 560, markiert }) {
323	  return (
