158	
159	function Legende({ eintraege }) {
160	  return (
161	    <ul className="mb-4 flex flex-wrap gap-x-5 gap-y-2 text-[13px] text-ink-600">
162	      {eintraege.map((e) => (
163	        <li key={e.label} className="flex items-center gap-2">
164	          {e.art === "linie" && <span aria-hidden="true" className="h-0.5 w-5 rounded-full" style={{ background: e.farbe }} />}
165	          {e.art === "strich" && <span aria-hidden="true" className="w-5 border-t-2 border-dashed" style={{ borderColor: e.farbe }} />}
166	          {e.art === "flaeche" && <span aria-hidden="true" className="h-3 w-5 rounded-sm ring-1 ring-ov-200" style={{ background: e.farbe }} />}
167	          {e.art === "balken" && <span aria-hidden="true" className="h-3 w-3 rounded-[3px]" style={{ background: e.farbe }} />}
168	          {e.label}
169	        </li>
170	      ))}
171	    </ul>
172	  );
173	}
174	
175	/** Gemeinsame Achsenlogik: Band-Skala nach Index, lineare y-Skala */
176	function useGeometrie(breite, n, yMin, yMax) {
177	  const H = breite < 520 ? 280 : 360;
178	  const m = { l: breite < 520 ? 40 : 48, r: 12, t: 26, b: 30 };
179	  const pw = Math.max(10, breite - m.l - m.r);
180	  const ph = H - m.t - m.b;
181	  const band = pw / Math.max(1, n);
182	  const x = (i) => m.l + band * (i + 0.5);
183	  const y = (v) => m.t + (1 - (v - yMin) / (yMax - yMin)) * ph;
184	  return { H, m, pw, ph, band, x, y };
185	}
186	
187	function Interaktion({ n, g, aktiv, setAktiv, label, children, breite }) {
188	  const ausPos = (clientX, el) => {
189	    const r = el.getBoundingClientRect();
190	    const i = Math.floor((clientX - r.left - g.m.l) / g.band);
191	    setAktiv(Math.max(0, Math.min(n - 1, i)));
192	  };
193	  return (
194	    <svg
195	      width="100%"
196	      height={g.H}
197	      viewBox={`0 0 ${breite} ${g.H}`}
198	      className="block touch-pan-y select-none outline-none focus-visible:ring-2 focus-visible:ring-ov-500 focus-visible:ring-offset-2 rounded-xl"
199	      role="img"
200	      aria-label={label}
201	      tabIndex={0}
202	      onPointerMove={(e) => ausPos(e.clientX, e.currentTarget)}
203	      onPointerDown={(e) => ausPos(e.clientX, e.currentTarget)}
204	      onPointerLeave={() => setAktiv(null)}
205	      onBlur={() => setAktiv(null)}
206	      onKeyDown={(e) => {
207	        if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
208	          e.preventDefault();
209	          const d = e.key === "ArrowRight" ? 1 : -1;
210	          setAktiv((a) => (a == null ? (d > 0 ? 0 : n - 1) : Math.max(0, Math.min(n - 1, a + d))));
211	        }
212	        if (e.key === "Escape") setAktiv(null);
213	      }}
214	    >
215	      {children}
216	    </svg>
217	  );
218	}
219	
220	function YAchse({ g, ticks, format, breite }) {
221	  return ticks.map((v) => (
222	    <g key={v}>
223	      <line x1={g.m.l} x2={breite - g.m.r} y1={g.y(v)} y2={g.y(v)} stroke={FARBE.raster} strokeWidth="1" />
224	      <text x={g.m.l - 8} y={g.y(v)} dy="0.32em" textAnchor="end" fontSize="11.5" fill={FARBE.achse} className="ov-num">
225	        {format(v)}
226	      </text>
227	    </g>
228	  ));
229	}
230	
231	/* ------------------------------------------------------------------ */
232	
233	function WerteDiagramm({ daten, lauf }) {
234	  const { t, fmt, termin, ct, mw } = useTeile();
235	  const [ref, breite] = useBreite(760);
236	  const [aktiv, setAktiv] = useState(null);
237	  const n = daten.length;
238	  const yMin = 3;
239	  const yMax = 9.5;
240	  const g = useGeometrie(breite, n, yMin, yMax);
241	  const ticks = [3, 4, 5, 6, 7, 8, 9];
242	
243	  const linie = daten.map((a, i) => `${i ? "L" : "M"}${g.x(i).toFixed(1)},${g.y(a.mittel).toFixed(1)}`).join("");
244	  const flaeche =
245	    daten.map((a, i) => `${i ? "L" : "M"}${g.x(i).toFixed(1)},${g.y(a.max).toFixed(1)}`).join("") +
246	    [...daten].reverse().map((a, k) => `L${g.x(n - 1 - k).toFixed(1)},${g.y(a.min).toFixed(1)}`).join("") +
247	    "Z";
248	  // Höchstwert als Treppenlinie über die Bandbreite je Termin
249	  const hoechst = daten
250	    .map((a, i) => {
251	      const x0 = g.m.l + g.band * i;
252	      const x1 = x0 + g.band;
253	      return `${i ? "L" : "M"}${x0.toFixed(1)},${g.y(a.hoechst).toFixed(1)}L${x1.toFixed(1)},${g.y(a.hoechst).toFixed(1)}`;
254	    })
255	    .join("");
256	
