334	function MengenDiagramm({ daten, lauf }) {
335	  const { t, f, fmt, mw } = useTeile();
336	  const [ref, breite] = useBreite(760);
337	  const [aktiv, setAktiv] = useState(null);
338	  const n = daten.length;
339	  const maxWert = Math.max(...daten.map((d) => Math.max(d.gebote, d.volumen)));
340	  const schritt = maxWert > 8000 ? 4000 : maxWert > 4000 ? 2000 : 1000;
341	  const yMax = Math.ceil(maxWert / schritt) * schritt;
342	  const g = useGeometrie(breite, n, 0, yMax);
343	  const ticks = Array.from({ length: yMax / schritt + 1 }, (_, k) => k * schritt);
344	  const bw = Math.min(28, (g.band - 10) / 2);
345	  const a = aktiv != null ? daten[aktiv] : null;
346	
347	  // Balken mit 4-px-Rundung oben, an der Grundlinie gerade
348	  const balken = (x, wert, farbe, key, i) => {
349	    const y0 = g.y(0);
350	    const y1 = g.y(wert);
351	    const h = Math.max(0, y0 - y1);
352	    const r = Math.min(4, h, bw / 2);
353	    const d = `M${x},${y0}V${y1 + r}Q${x},${y1} ${x + r},${y1}H${x + bw - r}Q${x + bw},${y1} ${x + bw},${y1 + r}V${y0}Z`;
354	    // Balken wachsen gestaffelt von der Grundlinie (transform, kein Layout)
355	    return <path key={key} d={d} fill={farbe} className="ov-balken-y" style={{ "--i": i }} />;
356	  };
357	
358	  return (
359	    <figure>
360	      <Legende
361	        eintraege={[
362	          { art: "balken", farbe: FARBE.gebote, label: t.legGebote },
