376	          {a && <rect x={g.m.l + g.band * aktiv + 2} y={g.m.t} width={g.band - 4} height={g.ph} rx="8" fill="#151a24" fillOpacity="0.04" />}
377	          {daten.map((d, i) => {
378	            const mitte = g.x(i);
379	            return (
380	              <g key={`${lauf}-${d.jahr}`}>
381	                {balken(mitte - bw - 1, d.gebote, FARBE.gebote, "g", i)}
382	                {balken(mitte + 1, d.zuschlag, FARBE.zuschlag, "z", i + 0.5)}
383	                <text x={mitte} y={g.H - 10} textAnchor="middle" fontSize="11.5" fill={FARBE.achse} className="ov-num">
384	                  {breite < 520 ? `’${String(d.jahr).slice(2)}` : d.jahr}
385	                </text>
386	              </g>
387	            );
388	          })}
389	        </Interaktion>
390	        {a && (
391	          <Tooltip x={g.x(aktiv)} y={g.y(Math.max(a.gebote, a.volumen)) - 10} breite={breite}>
392	            <p className="font-semibold">
393	              {a.jahr} · {a.termine} {t.termine(a.termine)}
394	            </p>
395	            <p>
396	              {t.ausgeschrieben} <strong className="ov-num">{mw(a.volumen)}</strong>
397	            </p>
398	            <p>
399	              {t.gebote} <strong className="ov-num">{mw(a.gebote)}</strong>
400	            </p>
401	            <p>
402	              {t.zuschlaegeL} <strong className="ov-num">{mw(a.zuschlag)}</strong>
403	            </p>
404	            <p className="text-white/75">
405	              {t.ueber(f, a.ueberzeichnung)} · Ø {fmt(a.mittel, 2)} ct
406	            </p>
407	          </Tooltip>
408	        )}
409	      </div>
410	      <figcaption className="mt-3 text-[12.5px] leading-relaxed text-ink-500">
411	        {t.mengenFuss(daten[n - 1].jahr)}
412	      </figcaption>
413	    </figure>
414	  );
415	}
