              <Scale aria-hidden="true" className="h-3.5 w-3.5" />
              {t.entwurf}
            </span>
            <span className="text-[13px] text-ink-500">{t.zweit(standText)}</span>
          </div>
          <div className="mt-8 flex flex-col gap-3 sm:flex-row">
